"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[15128],{96944:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"AimPoseController","desc":"The one per-frame driver of held weapons on every visible rig: player characters\\nand armed pirates (tagged `ArmedRig` by `EnemyGear`). It bends each rig\'s waist so\\nthe held tool points at that rig\'s aim point (`AimPose`), and for a gun-rig weapon\\n(`GunRig`) steps its gun and hands (`GunRigDriver`) right after, in the same frame.\\nAim tools = any `WeaponConfig` Tool (guns along the barrel; throwables from the\\nHandle along the chest), the Grabhook, and a pirate\'s `EnemyWeapon`.\\n- Local player: the crosshair point (screen-centre ray, as `GunHandler` aims),\\n  sent as `ReqAimPoint` at `AimPoseConfig.ReportHz` while a gun is held.\\n- Other players: the last relayed `AimPointSync` point; older than `StaleTime` = straight.\\n- Pirates: the root of the player named by the body\'s `AimTargetUserId` attribute\\n  (set by `EnemyBrain`; 0 = none).\\n- The pose editor\'s display copy (`WeaponPoseConfig.DisplayName`): held like its\\n  weapon (`HoldAnimConfig.holdName`), with no aim and no camera sway.\\nDead = plain animation. Throwables: the throw track (`HoldAnimConfig.Fire`) plays on\\ntop of the held pose. Runs on `PreSimulation` (after the\\nanimation step), and skips a rig whose Animator is throttled this frame.","realm":["Client"],"source":{"line":23,"path":"src/StarterPlayer/StarterPlayerScripts/AimPoseController.client.luau"}}')}}]);